// ============================================================
// BATCH SPLIT — CRITICAL FOR MULTIPLE EMAILS
// When Outlook Trigger picks up 4 emails at once,
// this node splits them into individual items so each
// email is processed independently, 1 by 1.
// This prevents data mixing between different senders.
// ============================================================
const items = $input.all();

const output = [];

for (const item of items) {
  // Self-email filter
  const myEmail = "YOUR_ASSISTANT_EMAIL@YOUR_DOMAIN.com";
  const from = (item.json.from?.emailAddress?.address || "").toLowerCase();
  if (from === myEmail.toLowerCase()) {
    continue; // skip self-sent emails
  }

  // Push each email as a separate, isolated item
  output.push({
    json: { ...item.json }
  });
}

return output;

