// Extract data from REPLY email
const text = 
  (typeof $json.body === "object" ? $json.body.content : $json.body) ||
  $json.bodyPreview ||
  "";
const clean = text
  .replace(/<[^>]+>/g, '\n')
  .replace(/&nbsp;/g, ' ')
  .replace(/\r\n/g, '\n')
  .replace(/\r/g, '\n');

const splitRegex = /\nOn[\s\S]*?wrote:|\nFrom:|\nSent:|\n---/i;
const parts = clean.split(splitRegex);
const message = parts[0].replace(/\n{2,}/g, '\n').trim();
const context = parts.length > 1 ? parts.slice(1).join("\n").trim().slice(0, 500) : "";

const invalidNames = ["there", "team", "support", "sir", "madam"];
const msgNameMatch = message.match(/(?:hi|hello|hey)\s+([A-Za-z]+)/i);
const msgName = msgNameMatch?.[1]?.trim();

const name = $json.from?.emailAddress?.name ||
  (!invalidNames.includes(msgName?.toLowerCase()) ? msgName : "") ||
  "there";

const email = ($json.from?.emailAddress?.address || "").toLowerCase().trim();

return [{
  json: {
    name,
    email,
    phone: "Not provided",
    message,
    context,
    source: "email",
    isReply: true,
    intent_hint: "reply_message"
  }
}];

// Extract data from NEW email
const text = 
  (typeof $json.body === "object" ? $json.body.content : $json.body) ||
  $json.bodyPreview ||
  "";
const clean = text
  .replace(/<[^>]+>/g, '\n')
  .replace(/&nbsp;/g, ' ')
  .replace(/\r\n/g, '\n')
  .replace(/\r/g, '\n');

const name  = clean.match(/(?:Name|Full Name):\s*(.+)/i)?.[1]?.trim() || $json.from?.emailAddress?.name || "there";
const email = (clean.match(/(?:E-?mail|E-Mail-Adresse):\s*(.+)/i)?.[1]?.trim() || $json.from?.emailAddress?.address || "").toLowerCase().trim();
const phone = clean.match(/(?:Phone|Telefon|Telefonnummer|Tel):\s*(.+)/i)?.[1]?.trim() || "Not provided";

const msgMatch = clean.match(/(?:Mes+age|Nachricht|Anliegen|Kommentar):\s*([\s\S]+?)(?:\n\s*---|$)/i);
const message = msgMatch ? msgMatch[1].trim() : clean.trim();

return [{
  json: {
    name,
    email,
    phone,
    message,
    context: "",
    source: "email",
    isReply: false,
    intent_hint: "new_lead"
  }
}];

