parameters.jsCode:
const items = $input.all();

for (const item of items) {
  let raw = item.json.text || "";

  const extract = (key) => {
    const regex = new RegExp(`"${key}"\\s*(?:\\\\?|\\\\n|[:\\s])*"(?:\\s*:\\s*)?(.*?)(?:"|\\\\")`, 'i');
    const match = raw.match(regex);
    if (match) {
      return match[1].replace(/\\n/g, ' ').replace(/\\"/g, '').replace(/^[:\s-]+/, '').trim();
    }
    return "";
  };

  try {
    const name = extract("Name");
    const phone = extract("Phone");
    const email = extract("Email");
    const message = extract("Message");
    const companyName = extract("Company Name") || extract("company");
    const meetingTime = extract("Meeting_Time");
    const text = extract("text");
    const actualDeptRaw = extract("actual_department");
    const context = extract("Previous Context") || extract("Context");
    const intentHint = extract("Message Type") || extract("intent_hint");

    const M_id = $('Get a message').item.json.id;

    const query = (message || text || "").toLowerCase();
    let amount = 0;
    let day = "";

    const moneyMatch = query.match(/(?:\$|usd|tk|taka)?\s*(\d+)/i);
    if (moneyMatch) amount = parseInt(moneyMatch[1]);
    if (/today/i.test(query)) day = "Today";
    else if (/tomorrow/i.test(query)) day = "Tomorrow";

    let actualDepartment = actualDeptRaw || "Sales";
    if (/support|problem|issue/i.test(query)) actualDepartment = "Customer Care";
    else if (/account|billing|payment/i.test(query)) actualDepartment = "Accounting";
    else if (/ceo|founder/i.test(query)) actualDepartment = "CEO";

    item.json = {
      Name: name,
      Phone: phone,
      Email: email,
      Message: message,
      Company: companyName || "Not provided",
      Meeting_Time: meetingTime || "Not provided",
      Context: context || "New email",
      intent_hint: intentHint || "new_email",
      day,
      text,
      actual_department: actualDepartment,
      amount,
      M_id
    };
  } catch (err) {
    item.json = { error: "Extraction failed", msg: err.message };
  }
}

return items;

