parameters.jsCode:
const items = $input.all();

for (const item of items) {
  let score = 0;

  const query = (
    $('Edit Fields2').item.json.Message ||
    item.json.Message || 
    item.json.message || 
    ""
  ).toLowerCase();

  const highIntent = ["buy","purchase","pricing","price","cost","start","subscribe","sign up","get started"];
  highIntent.forEach(w => { if (query.includes(w)) score += 50; });

  const demoIntent = ["demo","trial","interested","try","show me","walkthrough"];
  demoIntent.forEach(w => { if (query.includes(w)) score += 40; });

  const midIntent = ["tell me","about","details","explain","how","what"];
  midIntent.forEach(w => { if (query.includes(w)) score += 15; });

  const serviceIntent = ["service","solution","business","company","process","consultation"];
  serviceIntent.forEach(w => { if (query.includes(w)) score += 20; });

  const lowIntent = ["just checking","hello","hi","info","information"];
  lowIntent.forEach(w => { if (query.includes(w)) score -= 5; });

  score = Math.min(Math.max(score, 0), 100);

  let lead_type = "Cold";
  if (score >= 70) lead_type = "Hot";
  else if (score >= 40) lead_type = "Warm";

  const is_qualified = score >= 50;

  item.json.lead_score = score;
  item.json.lead_type = lead_type;
  item.json.is_qualified = is_qualified;
  item.json.followup_day = 0;
  item.json.followup_stopped = false;
  item.json.followup_client_name = $('Edit Fields2').item.json.Name || item.json.Name || "Valued Client";
  item.json.followup_client_email = $('Edit Fields2').item.json.Email || item.json.Email || "";
  item.json.followup_original_message = $('Edit Fields2').item.json.Message || item.json.Message || "";
}

return items;

